import{_ as a,b as n,f as l,I as e}from"./chunks/framework.DYvp_Vyw.js";const b=JSON.parse('{"title":"Matlab学习笔记004 - Matlab符号计算","description":"","frontmatter":{"title":"Matlab学习笔记004 - Matlab符号计算","date":"2025-05-06T13:44:14.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-007.md","filePath":"posts/Matlab-Own-Study-007.md"}'),p={name:"posts/Matlab-Own-Study-007.md"};function o(t,s,r,c,i,d){return l(),n("div",null,s[0]||(s[0]=[e(`<p>自己学习后整理的笔记（实时更新）</p><hr><h1 id="一、符号计算基础" tabindex="-1">一、符号计算基础 <a class="header-anchor" href="#一、符号计算基础" aria-label="Permalink to &quot;一、符号计算基础&quot;">​</a></h1><h2 id="一-定义符号变量" tabindex="-1">（一） 定义符号变量 <a class="header-anchor" href="#一-定义符号变量" aria-label="Permalink to &quot;（一） 定义符号变量&quot;">​</a></h2><p>参与符号运算的对象可以是符号变量、符号表达式或符号矩阵。符号变量要先定义，后引用。可以用sym函数、syms函数将运算量定义为符号型数据。引用符号运算函数时，用户可以指定函数执行过程中的变量参数；若用户没有指定变量参数，则使用findsym函数默认的变量作为函数的变量参数。</p><h3 id="_1、sym函数" tabindex="-1">1、<code>sym</code>函数 <a class="header-anchor" href="#_1、sym函数" aria-label="Permalink to &quot;1、\`sym\`函数&quot;">​</a></h3><p>sym函数的主要功能是创建符号变量，以便进行符号运算，也可以用于创建符号表达式或符号矩阵。用sym函数创建符号变量的一般格式为：</p><pre><code>            \`x = sym(‘x’)\`
</code></pre><p>其目的是将’x’创建为符号变量，以x作为输出变量名。每次调用该函数,可以定义一个符号变量。</p><h3 id="_2、syms函数" tabindex="-1">2、syms函数 <a class="header-anchor" href="#_2、syms函数" aria-label="Permalink to &quot;2、syms函数&quot;">​</a></h3><p>syms函数的功能与sym函数类似。syms函数可以在一个语句中同时定义多个符号变量，其一般格式为： <code>syms arg1 arg2 …argN</code><br> 用于将<code>rg1, arg2,…,argN</code>等符号创建为符号型数据。</p><h2 id="二-默认符号变量" tabindex="-1">（二）默认符号变量 <a class="header-anchor" href="#二-默认符号变量" aria-label="Permalink to &quot;（二）默认符号变量&quot;">​</a></h2><p>在数学表达式中，一般习惯于使用排在字母表中前面的字母作为变量的系数，而用排在后面的字母表示变量。例如： <code>f=ax2+bx+c</code> 表达式中的a,b,c通常被认为是常数，用作变量的系数；而将x看作自变量。 例如，数学表达式 <code>f=xn</code><code>g=sin(at+b)</code> 根据数学式中表示自变量的习惯，默认a,b,c为符号常数，x为符号变量。 若在MATLAB中表示上述表达式，首先用syms 函数定义a，b，n，t，x为符号对象。在进行导数运算时，由于没有指定符号变量，则系统采用数学习惯来确定表达式中的自变量，默认a,b,c为符号常数，x，t为符号变量。 即 ： 对函数f求导为：<code>df/dx</code> 对函数g求导为：<code>dg/dt</code></p><p>为了了解函数引用过程中使用的符号变量个数及变量名，可以用findsym函数查询默认的变量。该函数的引用格式为： <code>findsym（f,n）</code> 说明：f为用户定义的符号函数， n为正整数，表示查询变量的个数。 n=i,表示查询i个系统默认变量。n值省略时表示查询符号函数中全部系统默认变量。</p><h2 id="三-符号表达式详解" tabindex="-1">（三）符号表达式详解 <a class="header-anchor" href="#三-符号表达式详解" aria-label="Permalink to &quot;（三）符号表达式详解&quot;">​</a></h2><p>符号表达式是MATLAB符号数学工具箱的核心对象，由符号变量、数学运算符、函数调用等组成，可表示数学公式和方程式。</p><h3 id="_1-基本特性" tabindex="-1">1. 基本特性 <a class="header-anchor" href="#_1-基本特性" aria-label="Permalink to &quot;1. 基本特性&quot;">​</a></h3><ul><li><strong>与数值表达式的区别</strong>：保留数学形式而非立即计算</li><li><strong>显示特点</strong>：保持数学排版格式（如分数显示为竖式）</li><li><strong>运算规则</strong>：遵循数学运算优先级</li></ul><h3 id="_2-创建方法" tabindex="-1">2. 创建方法 <a class="header-anchor" href="#_2-创建方法" aria-label="Permalink to &quot;2. 创建方法&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 方法1：直接创建</span></span>
<span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> x</span></span>
<span class="line"><span style="color:#839496;">expr1 = x^2 </span><span style="color:#859900;">+</span><span style="color:#839496;"> sin(x) </span><span style="color:#859900;">-</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 方法2：使用sym函数</span></span>
<span class="line"><span style="color:#839496;">expr2 = sym(</span><span style="color:#2AA198;">&#39;y^2 + 2*y + 1&#39;</span><span style="color:#839496;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 方法3：从字符串转换</span></span>
<span class="line"><span style="color:#839496;">str = </span><span style="color:#2AA198;">&#39;exp(-z)*log(z)&#39;</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#839496;">expr3 = str2sym(str);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="_3-复合表达式示例" tabindex="-1">3. 复合表达式示例 <a class="header-anchor" href="#_3-复合表达式示例" aria-label="Permalink to &quot;3. 复合表达式示例&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> a b theta</span></span>
<span class="line"><span style="color:#839496;">expr4 = sqrt(a^2 </span><span style="color:#859900;">+</span><span style="color:#839496;"> b^2)*cos(theta-</span><span style="color:#B58900;">pi</span><span style="color:#839496;">/</span><span style="color:#D33682;">3</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#839496;">expr5 = piecewise(x </span><span style="color:#859900;">&lt;</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">, -</span><span style="color:#D33682;">1</span><span style="color:#839496;">, x </span><span style="color:#859900;">&gt;</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">, </span><span style="color:#D33682;">1</span><span style="color:#839496;">, </span><span style="color:#D33682;">0</span><span style="color:#839496;">);  </span><span style="color:#586E75;font-style:italic;">% 分段函数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="四-符号函数深入解析" tabindex="-1">（四）符号函数深入解析 <a class="header-anchor" href="#四-符号函数深入解析" aria-label="Permalink to &quot;（四）符号函数深入解析&quot;">​</a></h2><h3 id="_1-完整创建流程" tabindex="-1">1. 完整创建流程 <a class="header-anchor" href="#_1-完整创建流程" aria-label="Permalink to &quot;1. 完整创建流程&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> a b c x y positive  </span><span style="color:#586E75;font-style:italic;">% 定义正数符号变量</span></span>
<span class="line"><span style="color:#839496;">fxy = (a*x^2 </span><span style="color:#859900;">+</span><span style="color:#839496;"> b*y^2)/c^2 </span><span style="color:#859900;">+</span><span style="color:#839496;"> sqrt(x*y);  </span><span style="color:#586E75;font-style:italic;">% 复合符号函数</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 显示优化</span></span>
<span class="line"><span style="color:#839496;">fxy = simplify(fxy)  </span><span style="color:#586E75;font-style:italic;">% 代数化简</span></span>
<span class="line"><span style="color:#839496;">pretty(fxy)         </span><span style="color:#586E75;font-style:italic;">% 数学排版显示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_2-多变量函数处理" tabindex="-1">2. 多变量函数处理 <a class="header-anchor" href="#_2-多变量函数处理" aria-label="Permalink to &quot;2. 多变量函数处理&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> u v w</span></span>
<span class="line"><span style="color:#839496;">fuvw = u*v*exp(v/w) </span><span style="color:#859900;">+</span><span style="color:#839496;"> dirac(u-v);  </span><span style="color:#586E75;font-style:italic;">% 包含特殊函数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-函数操作示例" tabindex="-1">3. 函数操作示例 <a class="header-anchor" href="#_3-函数操作示例" aria-label="Permalink to &quot;3. 函数操作示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作类型</th><th>代码示例</th><th>说明</th></tr></thead><tbody><tr><td>求导</td><td><code>diff(fxy, x, 2)</code></td><td>对x求二阶导</td></tr><tr><td>积分</td><td><code>int(fxy, y, 0, inf)</code></td><td>对y从0到∞积分</td></tr><tr><td>代入计算</td><td><code>subs(fxy, [a,b,c], [1,2,3])</code></td><td>替换特定参数值</td></tr><tr><td>方程求解</td><td><code>solve(fxy == 0, x)</code></td><td>解方程</td></tr><tr><td>泰勒展开</td><td><code>taylor(fxy, x, &#39;ExpansionPoint&#39;, 0, &#39;Order&#39;, 5)</code></td><td>在x=0处5阶展开</td></tr></tbody></table><h3 id="_4-高级应用示例" tabindex="-1">4. 高级应用示例 <a class="header-anchor" href="#_4-高级应用示例" aria-label="Permalink to &quot;4. 高级应用示例&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 微分方程求解</span></span>
<span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> y(t)</span></span>
<span class="line"><span style="color:#839496;">ode = diff(y,t,</span><span style="color:#D33682;">2</span><span style="color:#839496;">) </span><span style="color:#859900;">+</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">*diff(y,t) </span><span style="color:#859900;">+</span><span style="color:#839496;"> y </span><span style="color:#859900;">==</span><span style="color:#839496;"> exp(-t);</span></span>
<span class="line"><span style="color:#839496;">dsolve(ode)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 矩阵符号运算</span></span>
<span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> A [2 2]</span></span>
<span class="line"><span style="color:#839496;">B = inv(A)</span><span style="color:#859900;">&#39;</span><span style="color:#859900;"> *</span><span style="color:#839496;"> det(A)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 变量类型限定</span></span>
<span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> x real          </span><span style="color:#586E75;font-style:italic;">% 实数变量</span></span>
<span class="line"><span style="color:#268BD2;">syms</span><span style="color:#2AA198;"> n integer       </span><span style="color:#586E75;font-style:italic;">% 整数变量</span></span>
<span class="line"><span style="color:#839496;">assume(x </span><span style="color:#859900;">&gt;</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">)        </span><span style="color:#586E75;font-style:italic;">% 附加约束条件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_5-可视化支持" tabindex="-1">5. 可视化支持 <a class="header-anchor" href="#_5-可视化支持" aria-label="Permalink to &quot;5. 可视化支持&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 二维函数绘图</span></span>
<span class="line"><span style="color:#839496;">fplot(sin(x)/x, [-</span><span style="color:#D33682;">20</span><span style="color:#D33682;"> 20</span><span style="color:#839496;">])</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 三维隐函数绘图</span></span>
<span class="line"><span style="color:#839496;">fsurf(x^2 </span><span style="color:#859900;">+</span><span style="color:#839496;"> y^2 </span><span style="color:#859900;">-</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">, [-</span><span style="color:#D33682;">1.5</span><span style="color:#D33682;"> 1.5</span><span style="color:#839496;"> -</span><span style="color:#D33682;">1.5</span><span style="color:#D33682;"> 1.5</span><span style="color:#839496;">])</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 等高线图</span></span>
<span class="line"><span style="color:#839496;">fcontour(fxy, </span><span style="color:#2AA198;">&#39;Fill&#39;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&#39;on&#39;</span><span style="color:#839496;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><blockquote><p>​<strong>​注​</strong>​：符号计算会占用较多内存，复杂运算建议：</p><ol><li>使用<code>simplify</code>定期化简</li><li>对不需要的符号变量用<code>clear</code>释放</li><li>数值计算部分可转为<code>vpa</code>或<code>double</code></li></ol></blockquote><h3 id="_6-符号与数值转换" tabindex="-1">6. 符号与数值转换 <a class="header-anchor" href="#_6-符号与数值转换" aria-label="Permalink to &quot;6. 符号与数值转换&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 符号转数值</span></span>
<span class="line"><span style="color:#839496;">num_val = double(subs(fxy, [a,b,c,x,y], [</span><span style="color:#D33682;">1.1</span><span style="color:#839496;">, </span><span style="color:#D33682;">2.3</span><span style="color:#839496;">, </span><span style="color:#D33682;">0.5</span><span style="color:#839496;">, </span><span style="color:#B58900;">pi</span><span style="color:#839496;">, </span><span style="color:#D33682;">2</span><span style="color:#839496;">*</span><span style="color:#B58900;">pi</span><span style="color:#839496;">]))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 高精度计算</span></span>
<span class="line"><span style="color:#839496;">vpa_val = vpa(subs(fxy, [a,b,c,x,y], [sqrt(</span><span style="color:#D33682;">2</span><span style="color:#839496;">), </span><span style="color:#B58900;">pi</span><span style="color:#839496;">, </span><span style="color:#D33682;">1</span><span style="color:#839496;">/</span><span style="color:#D33682;">3</span><span style="color:#839496;">, </span><span style="color:#D33682;">2</span><span style="color:#839496;">, </span><span style="color:#D33682;">3</span><span style="color:#839496;">]), </span><span style="color:#D33682;">50</span><span style="color:#839496;">)  </span><span style="color:#586E75;font-style:italic;">% 50位精度</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h1 id="二、微积分" tabindex="-1">二、微积分 <a class="header-anchor" href="#二、微积分" aria-label="Permalink to &quot;二、微积分&quot;">​</a></h1><h2 id="一-微积分函数" tabindex="-1">（一） 微积分函数 <a class="header-anchor" href="#一-微积分函数" aria-label="Permalink to &quot;（一） 微积分函数&quot;">​</a></h2><h3 id="_1-求极限" tabindex="-1">1.求极限 <a class="header-anchor" href="#_1-求极限" aria-label="Permalink to &quot;1.求极限&quot;">​</a></h3><p>函数limit用于求符号函数f的极限。系统可以根据用户要求，计算变量从不同方向趋近于指定值的极限值。该函数的格式及功能： <code>limit(f,x,a)</code>：求符号函数f（x）的极限值。即计算当变量x趋近于常数a时，f（x）函数的极限值。 <code>limit(f,a)</code>：求符号函数f（x）的极限值。由于没有指定符号函数f（x）的自变量，则使用该格式时，符号函数f（x）的变量为函数findsym(f)确定的默认自变量，既变量x趋近于a。 <code>limit(f)</code>：求符号函数f（x）的极限值。符号函数f（x）的变量为函数findsym(f)确定的默认变量；没有指定变量的目标值时，系统默认变量趋近于0，即a=0的情况。 <code>limit(f,x,a,&#39;right&#39;)</code>：求符号函数f的极限值。&#39;right&#39;表示变量x从右边趋近于a。 <code>limit(f,x,a,&#39;left&#39;)</code>：求符号函数f的极限值。&#39;left&#39;表示变量x从左边趋近于a。</p><h3 id="_2-微分函数" tabindex="-1">2. 微分函数 <a class="header-anchor" href="#_2-微分函数" aria-label="Permalink to &quot;2. 微分函数&quot;">​</a></h3><p>diff函数用于对符号表达式s求微分。该函数的一般引用格式为：<br><code>diff(s,’v’,n)</code> 说明： 应用diff（s）没有指定微分变量和微分阶数，则系统按findsym函数指示的默认变量对符号表达式s求一阶微分。 应用diff（s，‘v’）或diff（s，sym（‘v’）） 格式，表示以v为自变量，对符号表达式s求一阶微分。 应用diff（s，n）格式，表示对符号表达式s求n阶微分，n为正整数。<br> 应用diff（s，‘v’，n）diff（s，n，‘v’） 格式，表示以v为自变量，对符号表达式s求n阶微分。</p><h3 id="_3-积分函数" tabindex="-1">3．积分函数 <a class="header-anchor" href="#_3-积分函数" aria-label="Permalink to &quot;3．积分函数&quot;">​</a></h3><p>积分函数<code>int（s ，v，a，b)</code>可以对被积函数或符号表达式s求积分。其引用格式为： <code>int（s ，v，a，b)</code> 说明： 应用int（s）格式，表示没有指定积分变量和积分阶数时，系统按findsym函数指示的默认变量对被积函数或符号表达式s求一阶积分。 应用int（s，v）格式，表示以v为自变量，对被积函数或符号表达式s求一阶不定积分。 应用积分函数时，如果给定 a、b两项，表示是进行定积分运算。a、b分别表示定积分的下限和上限。不指定积分的下限和上限表示求不定积分。</p><h3 id="_4-级数-级数求和" tabindex="-1">4. 级数(级数求和) <a class="header-anchor" href="#_4-级数-级数求和" aria-label="Permalink to &quot;4. 级数(级数求和)&quot;">​</a></h3><p>级数求和运算是数学中常见的一种运算。例如： f(x)=a<sub>0</sub>+a<sub>1</sub>x+a<sub>2</sub>x<sup>2</sup>+a<sub>3</sub>x<sup>3</sup>+…+a<sub>n</sub>x<sup>n</sup> 函数symsum可以用于此类对符号函数f的求和运算。该函数的引用时，应确定级数的通项式s，变量的变化范围a和b。该函数的引用格式为： <code>symsum(s, a,b)</code></p><h1 id="三、简化方程表达式" tabindex="-1">三、简化方程表达式 <a class="header-anchor" href="#三、简化方程表达式" aria-label="Permalink to &quot;三、简化方程表达式&quot;">​</a></h1><h2 id="_1-因式分解" tabindex="-1">1.因式分解 <a class="header-anchor" href="#_1-因式分解" aria-label="Permalink to &quot;1.因式分解&quot;">​</a></h2><p>factor函数的功能为：把多项式S分解为多个因式，各多项式的系数均为有理数。格式为：<br><code>factor(s)</code></p><h2 id="_2-嵌套" tabindex="-1">2.嵌套 <a class="header-anchor" href="#_2-嵌套" aria-label="Permalink to &quot;2.嵌套&quot;">​</a></h2><p>将符号多项式s用嵌套形式表示，即用多层括号的形式表示。Horner函数可以实现此功能。该函数的格式为： <code>horner(s)</code></p><h1 id="四、解方程" tabindex="-1">四、解方程 <a class="header-anchor" href="#四、解方程" aria-label="Permalink to &quot;四、解方程&quot;">​</a></h1><p>解方程函数的格式为：</p><p><code>solve(expr1,expr2,...,exprN,var1,var2,...varN)</code> 或 <code>solve(expr1,expr2,...,exprN)</code> 其功能为：求解代数方程组expr1,expr2,...,exprN的根，未知数为var1,var2,...varN。 说明： 若不指明符号表达式expr1,expr2,...,exprN的值，系统默认为0。例如给出一个表达式x^2-3<em>x-8,则系统将按x^2-3</em>x-8=0进行运算；</p><hr>`,55)]))}const u=a(p,[["render",o]]);export{b as __pageData,u as default};
